Пример для **TON mainnet и горячего кошелька V4R2**. Версия и `walletId` должны соответствовать вашему кошельку. Зависимости: `@ton/ton`, `@ton/core`, `@ton/crypto`; TypeScript с `target: ES2020` или выше.

```ts
import {
  Address,
  beginCell,
  internal,
  JettonMaster,
  SendMode,
  TonClient,
  toNano,
  WalletContractV4,
} from "@ton/ton";
import { mnemonicToPrivateKey, mnemonicValidate } from "@ton/crypto";
import { randomBytes } from "node:crypto";

function env(name: string): string {
  const value = process.env[name]?.trim();
  if (!value) throw new Error(`Не задана ${name}`);
  return value;
}

async function main() {
  const client = new TonClient({
    endpoint: "https://toncenter.com/api/v2/jsonRPC",
    apiKey: env("TONCENTER_API_KEY"),
  });

  // Секрет поступает из окружения, не храните его в исходниках.
  const words = env("HOT_WALLET_MNEMONIC").split(/\s+/);
  if (!(await mnemonicValidate(words))) {
    throw new Error("Некорректная TON-мнемоника");
  }
  const keys = await mnemonicToPrivateKey(words);

  const wallet = client.open(
    WalletContractV4.create({
      workchain: 0,
      publicKey: keys.publicKey,
      walletId: 698983191, // стандартный ID V4R2
    }),
  );

  if (!wallet.address.equals(Address.parse(env("HOT_WALLET_ADDRESS")))) {
    throw new Error("Адрес не совпал: проверьте ключ, версию и walletId");
  }

  // Обычный TON-адрес пользователя.
  const recipient = Address.parse(env("RECIPIENT_ADDRESS"));

  // Доверенный master настоящего USDT в mainnet.
  const usdtMaster = Address.parse(
    "EQCxE6mUtQJKFnGfaROTKOt1lZbDiiX1kCixRv7Nw2Id_sDs",
  );
  const master = client.open(JettonMaster.create(usdtMaster));
  const senderJettonWallet = await master.getWalletAddress(wallet.address);

  const { stack } = await client.runMethod(
    senderJettonWallet,
    "get_wallet_data",
  );
  const balance = stack.readBigNumber();
  const owner = stack.readAddress();
  const masterAddress = stack.readAddress();

  if (!owner.equals(wallet.address) || !masterAddress.equals(usdtMaster)) {
    throw new Error("Неверный USDT jetton-wallet");
  }

  const amount = 25_000_000n; // 25 USDT × 10^6; НЕ toNano("25")
  if (balance < amount) throw new Error("Недостаточно USDT");

  const attachedTon = toNano("0.1"); // бюджет выполнения, не точная комиссия
  if ((await wallet.getBalance()) < attachedTon + toNano("0.02")) {
    throw new Error("Недостаточно TON на выполнение и комиссии");
  }

  const queryId = randomBytes(8).readBigUInt64BE();

  const body = beginCell()
    .storeUint(0x0f8a7ea5, 32)       // jetton transfer
    .storeUint(queryId, 64)
    .storeCoins(amount)
    .storeAddress(recipient)        // новый владелец USDT
    .storeAddress(wallet.address)   // возврат лишних TON
    .storeBit(false)                // custom_payload отсутствует
    .storeCoins(1n)                 // 1 nanoton для transfer_notification
    .storeBit(false)                // пустой inline forward_payload
    .endCell();

  // Выплаты из этого кошелька должны выполняться последовательно.
  const seqno = await wallet.getSeqno();

  // В production сохраните выплату и queryId в БД ДО отправки.
  console.log({ queryId: queryId.toString(), seqno });

  await wallet.sendTransfer({
    seqno,
    secretKey: keys.secretKey,
    timeout: Math.floor(Date.now() / 1000) + 120,
    sendMode: SendMode.PAY_GAS_SEPARATELY | SendMode.IGNORE_ERRORS,
    messages: [
      internal({
        to: senderJettonWallet, // USDT jetton-wallet ОТПРАВИТЕЛЯ
        value: attachedTon,
        bounce: true,
        body,
      }),
    ],
  });

  console.log("Запрос отправлен; получение USDT ещё нужно подтвердить.");
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
```

У USDT **6 decimals**, поэтому отправляется ровно `25_000_000n` минимальных единиц. Сообщение направляется в jetton-wallet отправителя; адрес пользователя находится в `destination`. TON оплачивает выполнение, остаток возвращается горячему кошельку.

`sendTransfer()` и рост `seqno` не подтверждают доставку USDT: проверяйте успешную цепочку транзакций до jetton-wallet получателя. После тайм-аута сначала выясните результат; `queryId` сам по себе не предотвращает повторную выплату.

Формат сообщения: [TEP-74](https://github.com/ton-blockchain/TEPs/blob/master/text/0074-jettons-standard.md).
